const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artikuli</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Немецкий артикль не всегда совпадает с латышской семьей. Поэтому существительные лучше всего учить вместе с артиклем.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Примеры статей</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — galds</div>\n      <div class=\"kurss-example\">die Tür — durvis</div>\n      <div class=\"kurss-example\">das Messer — nazis</div>\n      <div class=\"kurss-example\">das Mädchen — meitene</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Часто ДЭР</h4>\n    <p class=\"artikuli-explain\">DER часто представляет собой лица мужского пола, дни, месяцы, времена года и некоторые слова с определенными окончаниями.</p>\n\n    <h5 class=\"artikuli-subtitle\">Noteikumi</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → bieži DER, piemēram: der Computer, der Lehrer <span class=\"artikuli-note\">Но не всегда</span></div>\n      <div class=\"kurss-example\">-ling → часто DER, например: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → часто DER, например: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">Лица мужского пола → der Mann, der Vater</div>\n      <div class=\"kurss-example\">profesijas → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">Марки автомобилей → подходит BMW, подходит Mercedes</div>\n      <div class=\"kurss-example\">dienas → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">Месяцы → Август, Декабрь</div>\n      <div class=\"kurss-example\">gadalaiki → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примеры</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">Дер Манн - мужчина</div>\n      <div class=\"kurss-example\">Дер Фатер — отец</div>\n      <div class=\"kurss-example\">der Montag — pirmdiena</div>\n      <div class=\"kurss-example\">der August — augusts</div>\n      <div class=\"kurss-example\">der Sommer — vasara</div>\n      <div class=\"kurss-example\">Дер Лерер - учитель</div>\n      <div class=\"kurss-example\">der Computer — dators</div>\n      <div class=\"kurss-example\">der Schmetterling — taurenis</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Часто УМИРАЮТ</h4>\n    <p class=\"artikuli-explain\">DIE часто бывает женского рода, множественного числа, и слова оканчиваются на -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Noteikumi</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">Лица женского пола → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motociklu markas → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">daudzskaitlis → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">Почти всегда множественное число → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примеры</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — sieviete</div>\n      <div class=\"kurss-example\">Умереть Муттер — мать</div>\n      <div class=\"kurss-example\">Die Wohnung — квартира</div>\n      <div class=\"kurss-example\">Die Rechnung - счет</div>\n      <div class=\"kurss-example\">Die Freiheit – свобода</div>\n      <div class=\"kurss-example\">Die Möglichkeit - возможность</div>\n      <div class=\"kurss-example\">die Mannschaft — komanda</div>\n      <div class=\"kurss-example\">Умереть нация — нация</div>\n      <div class=\"kurss-example\">Die Universität — университет</div>\n      <div class=\"kurss-example\">die Polizei — policija</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Часто ДАС</h4>\n    <p class=\"artikuli-explain\">В DAS часто встречаются уменьшительные формы с -chen/-lein, во многих словах с -ment/-um и глаголы в виде существительных.</p>\n\n    <h5 class=\"artikuli-subtitle\">Noteikumi</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">Металлы → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">Химические элементы → дас Эйзен, дас Зауэрстофф</div>\n      <div class=\"kurss-example\">Отели → Дас Отель</div>\n      <div class=\"kurss-example\">Цвета как существительные → das Rot, das Blau</div>\n      <div class=\"kurss-example\">Глагол как существительное → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">Глаголы как существительные → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примеры</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">Das Kind - ребенок</div>\n      <div class=\"kurss-example\">das Mädchen — meitene</div>\n      <div class=\"kurss-example\">Дас Хойшен - коттедж</div>\n      <div class=\"kurss-example\">das Instrument — instruments</div>\n      <div class=\"kurss-example\">das Zentrum — centrs</div>\n      <div class=\"kurss-example\">das Museum — muzejs</div>\n      <div class=\"kurss-example\">Дас Эссен - еда / еда</div>\n      <div class=\"kurss-example\">Дас Лернен - ​​обучение</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Важные исключения / необходимо узнать из статьи</h4>\n    <p class=\"artikuli-explain\">По некоторым словам артикль не может быть достоверно определен ни по окончанию, ни по латышской семье. Их лучше всего изучать вместе со статьей.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — durvis</div>\n      <div class=\"kurss-example\">das Messer — nazis</div>\n      <div class=\"kurss-example\">die Sonne — saule</div>\n      <div class=\"kurss-example\">Дер Монд — луна</div>\n      <div class=\"kurss-example\">das Mädchen — meitene</div>\n      <div class=\"kurss-example\">Дас авто - автомобиль</div>\n      <div class=\"kurss-example\">der Käse — siers</div>\n      <div class=\"kurss-example\">Ди Габель - вилка</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Окончания и группы слов помогают угадать артикль, но они не являются 100%-ным правилом. Если не уверены, выучите слово с артиклем.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Местоимения</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Номинатив, Аккусатив и Датив – формы местоимений.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — kas?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — es</div><div class=\"kurss-example\">du — tu</div><div class=\"kurss-example\">Э-э - он</div><div class=\"kurss-example\">Си - она</div><div class=\"kurss-example\">es — tas</div><div class=\"kurss-example\">Вир - мы</div><div class=\"kurss-example\">Ихр — ты</div><div class=\"kurss-example\">Sie - они/ее</div><div class=\"kurss-example\">Sie – Ты (любезно предоставлено)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — ko?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mani</div><div class=\"kurss-example\">dich — tevi</div><div class=\"kurss-example\">Ihn – их (глаг.)</div><div class=\"kurss-example\">Sie – его (с.)</div><div class=\"kurss-example\">es — to</div><div class=\"kurss-example\">Мы - мы</div><div class=\"kurss-example\">Ой - ты</div><div class=\"kurss-example\">Sie – их/ее</div><div class=\"kurss-example\">Sie – Ты (любезно предоставлено)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — kam?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — man</div><div class=\"kurss-example\">dir — tev</div><div class=\"kurss-example\">Я - для него / для этого</div><div class=\"kurss-example\">Ихр — для нее</div><div class=\"kurss-example\">uns — mums</div><div class=\"kurss-example\">euch — jums</div><div class=\"kurss-example\">Ihnen – для них/них</div><div class=\"kurss-example\">Инен – Тебе (любезно)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Как выбрать форму?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — teikuma priekšmets (kas dara?)</li><li><span class=\"case-red\">Akkusativ</span> — tiešais objekts (ko?)</li><li><span class=\"case-green\">Dativ</span> — netiešais objekts (kam?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Примеры</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Es tevi redzu.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Я вижу его.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Ты нам нравишься.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Я помогаю тебе.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Es dodu viņam grāmatu.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Мы благодарим вас.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ vienmēr ir teikuma priekšmets, bet Akkusativ un Dativ — objekti. Skaties uz darbības vārdu un jautā: <span class=\"case-red\">ko?</span> vai <span class=\"case-green\">kam?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Гласные – долгие и краткие</h3>\n            <p class=\"kurss-lesson-intro\">В немецком языке гласные могут быть долгими и краткими. Это влияет на произношение слова.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Долгая гласная</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — silts</div><div class=\"kurss-example\">Гут (получить) — хорошо</div><div class=\"kurss-example\">Тат (тат) – работа/действие</div><div class=\"kurss-example\">Флур (flūr) – прихожая</div><div class=\"kurss-example\">Weg (вег) – дорога</div><div class=\"kurss-example\">Хата (hūt) – шапка</div><div class=\"kurss-example\">Hof (hōf) — pagalms</div><div class=\"kurss-example\">Шлаф – спать</div></div>\n              <p>Если за гласной следует одна согласная, гласная часто произносится долго.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Краткая гласная</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Пильц (pilc) – гриб</div><div class=\"kurss-example\">Ворт (vort) – слово</div><div class=\"kurss-example\">Mund (munt) — mute</div><div class=\"kurss-example\">Лысый (белый) – скоро</div><div class=\"kurss-example\">Шарф (шарф) – острый</div><div class=\"kurss-example\">Feld (felt) — lauks</div><div class=\"kurss-example\">voll (fol) — pilns</div></div>\n              <p>Когда за гласной следуют две или более согласных, гласная часто произносится кратко.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Galotnes en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Singen (зинген) — петь</div><div class=\"kurss-example\">Tragen (trägen) — нести</div><div class=\"kurss-example\">Garten (сад) – сад</div><div class=\"kurss-example\">Vogel (fogel) — putns</div><div class=\"kurss-example\">Сегель - парус</div><div class=\"kurss-example\">Братен (брат) – жаркое</div><div class=\"kurss-example\">Bogen (bōgen) — loks</div><div class=\"kurss-example\">Шпигель (spiegel) – зеркало</div><div class=\"kurss-example\">Finger (finger) — pirksts</div><div class=\"kurss-example\">Холтер (холтер) – держатель</div><div class=\"kurss-example\">Arbeiter (арбайтер) — рабочий</div><div class=\"kurss-example\">Хойзер (хойзер) - дома</div><div class=\"kurss-example\">Видер - снова</div><div class=\"kurss-example\">Брейтер (брайтер) – шире</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Буква h как долгота</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Рахмен (rämen) – рамка</div><div class=\"kurss-example\">Ohr (ōr) — auss</div><div class=\"kurss-example\">Kohle (kōle) — ogles</div><div class=\"kurss-example\">Заль (курица) – число</div><div class=\"kurss-example\">Ihn (īn) – его</div><div class=\"kurss-example\">Ихм (īm) — ему</div><div class=\"kurss-example\">Хун (хун) – курица</div><div class=\"kurss-example\">Нахм (нам) — взял</div><div class=\"kurss-example\">Немен (nēmen) – брать</div><div class=\"kurss-example\">Шух - туфелька</div></div>\n              <p>В некоторых словах h удлиняет предыдущую гласную. В таких случаях буква h обычно не произносится.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Galotnes ar e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lampa</div><div class=\"kurss-example\">Хасэ (дымка) – заяц</div><div class=\"kurss-example\">Кнабе (клюв) – мальчик</div><div class=\"kurss-example\">Рабе – ворон</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Garais i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Die (dī) — артикль «умереть»</div><div class=\"kurss-example\">Diese - это/эти</div><div class=\"kurss-example\">Видер - снова</div><div class=\"kurss-example\">Fliege (флиж) — летать</div><div class=\"kurss-example\">Зиеге (циге) – козел</div><div class=\"kurss-example\">Stiel (стил) – стебель</div><div class=\"kurss-example\">Диб (दीप) - вор</div><div class=\"kurss-example\">Hier (хир) – здесь</div></div>\n              <p>Long i по-немецки часто пишется как ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Двойные гласные</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Саал (трава) – зал</div><div class=\"kurss-example\">Саат (зять) – посев</div><div class=\"kurss-example\">Staat (государство) – страна</div><div class=\"kurss-example\">Бире (похоронное) – ягода</div><div class=\"kurss-example\">See (zee) – озеро/море</div><div class=\"kurss-example\">Свекла (бет) – грядка</div><div class=\"kurss-example\">Boot (bōt) — laiva</div><div class=\"kurss-example\">Moor (mōr) — purvs</div><div class=\"kurss-example\">Моос (mōs) – мох</div></div>\n              <p>Двойные гласные обычно произносятся долго.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — siena</div><div class=\"kurss-example\">Wände (vende) — sienas</div><div class=\"kurss-example\">Фатер (отец) — отец</div><div class=\"kurss-example\">Väter (fēter) – отцы</div><div class=\"kurss-example\">Шранк (шранк) – кабинет</div><div class=\"kurss-example\">Шренке (schrenke) – шкафы</div><div class=\"kurss-example\">Bank (bank) — sols / banka</div><div class=\"kurss-example\">Bänke (benke) — soli</div><div class=\"kurss-example\">Таль (дальний) – долина</div><div class=\"kurss-example\">Талер (tēler) - долины</div></div>\n              <p>Ä является транспозицией a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōze) — roze</div><div class=\"kurss-example\">Рёшен (rēschen) – розетка</div><div class=\"kurss-example\">Офен (ōfen) – печь</div><div class=\"kurss-example\">Офен (öfen) – печи</div><div class=\"kurss-example\">Рок (рок) – юбка</div><div class=\"kurss-example\">Рёкке (röke) – юбка</div></div>\n              <p>Ö — это настройка о.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Курц (kurc) — короткий</div><div class=\"kurss-example\">Kürzer (курцер) – короче</div><div class=\"kurss-example\">Кунст (kunst) — искусство</div><div class=\"kurss-example\">Кюнсте (künste) — искусство</div><div class=\"kurss-example\">Муттер (муттер) – мать</div><div class=\"kurss-example\">Мюттер (муттер) – матери</div></div>\n              <p>Ü — это транспозиция слова u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — koks</div><div class=\"kurss-example\">Bäume (boime) — koki</div><div class=\"kurss-example\">Haus (хаус) — дом</div><div class=\"kurss-example\">Хойзер (хойзер) - дома</div><div class=\"kurss-example\">Штраух (štrauh) – куст</div><div class=\"kurss-example\">Штройхер (štroiher) - кусты</div><div class=\"kurss-example\">Maus (maus) — pele</div><div class=\"kurss-example\">Mäuse (moize) — peles</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Хойте (хойте) — сегодня</div><div class=\"kurss-example\">Леуте (лойте) – люди</div><div class=\"kurss-example\">neu (noi) — jauns</div><div class=\"kurss-example\">Нейн (ноин) – девять</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: эй</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — mans</div><div class=\"kurss-example\">dein (dain) — tavs</div><div class=\"kurss-example\">Sein (заин) – она/ее/быть</div><div class=\"kurss-example\">Frei (фрай) – свободный</div><div class=\"kurss-example\">Arbeiten (арбайтен) — работать</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Лекция 2, примечания к произношению</h4>\n              <ul class=\"kurss-summary-list\"><li>В словах ich, nicht, rechnen, zeichnen «ч» произносится мягко</li><li>В arbeiten и zeichnen «ei» произносится как «ai».</li><li>\"sp\" в начале слова произносится как \"šp\"</li><li>В глаголе тун буква «у» произносится долго</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kopsavilkums</h4>\n              <ul class=\"kurss-summary-list\"><li>Одна согласная после гласной → часто долгая гласная</li><li>Две или более согласных → часто короткая гласная</li><li>H может удлинить гласную</li><li>Т.е. часто стоит долго i</li><li>Двойные гласные обычно длинные</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Согласные и буквосочетания</h3>\n            <p class=\"kurss-lesson-intro\">В немецком языке некоторые согласные и буквосочетания произносятся иначе, чем пишутся. В этой лекции собраны самые важные примеры для новичка.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Согласные</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Дас Рад (рат) — колесо</div><div class=\"kurss-example\">Die Räder (радер) — колеса</div><div class=\"kurss-example\">Бад (बाट) – баня</div><div class=\"kurss-example\">Бэдер (bäder) – бани</div></div>\n              <p>Согласные в конце слова часто произносятся не так, как пишутся.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>«Ч» может произноситься как мягко, так и твердо. В одних словах оно звучит как «ч», в других ближе к «к».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rehnen (ренен) — вычислять</div><div class=\"kurss-example\">Zeichnen (caihnen) — рисовать</div><div class=\"kurss-example\">nicht (niht) — ne</div><div class=\"kurss-example\">Schlecht (шлехт) – плохой</div><div class=\"kurss-example\">mich (mih) — mani</div><div class=\"kurss-example\">dich (dih) — tevi</div><div class=\"kurss-example\">Штраух (štrauh) – куст</div><div class=\"kurss-example\">Ноч (нох) – еще</div><div class=\"kurss-example\">Nacht (naht) — nakts</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>«sch» по-немецки произносится как латышское «š».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Шуле - школа</div><div class=\"kurss-example\">Шулер (schüler) – студент</div><div class=\"kurss-example\">Шифф (шиф) – корабль</div><div class=\"kurss-example\">Шраубе (винт) – винт</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Sp и st в начале слова</h4>\n              <p>В начале слова или слога «sp» часто произносится как «šp», а «st» — как «št».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielen (шпилен) – играть</div><div class=\"kurss-example\">Прыгнул - прыжок</div><div class=\"kurss-example\">Stehen (стин) – стоять</div><div class=\"kurss-example\">Стойло (штал) - сарай</div><div class=\"kurss-example\">Стенд (stant) – положение/место</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>«Цюй» в немецком языке обычно произносится как «кв».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Куал (квал) – мучение</div><div class=\"kurss-example\">Quartier (квартье) – квартал/жилье</div><div class=\"kurss-example\">Quer (квер) — поперек</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s un z</h4>\n              <p>«С» в начале слова часто звучит как «з». Буква «з» в немецком языке звучит как латвийская «ц».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Sagen (zagen) — говорить</div><div class=\"kurss-example\">Singen (зинген) — петь</div><div class=\"kurss-example\">Rose (rōze) — roze</div><div class=\"kurss-example\">Заль (курица) – число</div><div class=\"kurss-example\">Zeit (cait) — laiks</div><div class=\"kurss-example\">Zink (cink) — cinks</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>В немецком языке буква «v» часто произносится как «f». В иностранных словах оно часто звучит как латвийское «в».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Фатер (отец) — отец</div><div class=\"kurss-example\">von (fon) — no</div><div class=\"kurss-example\">Виэль (фил) — много</div><div class=\"kurss-example\">Vier (фир) — четыре</div><div class=\"kurss-example\">Villa (villa) — villa</div><div class=\"kurss-example\">Клавир (фортепиано) – фортепиано</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x un y</h4>\n              <p>«х» произносится как «кс». «y» в некоторых словах произносится как «ü».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Феликс (Felix) – Феликс</div><div class=\"kurss-example\">Axt (akst) — cirvis</div><div class=\"kurss-example\">Мистика (мустик) – мистика</div><div class=\"kurss-example\">Никс - Никс</div><div class=\"kurss-example\">Миф (рот) – миф</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>«ß» в немецком языке произносится как «s».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Фусс - нога</div><div class=\"kurss-example\">Füße (фюсе) – ноги</div><div class=\"kurss-example\">Грюссе - привет</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kopsavilkums</h4>\n              <ul class=\"kurss-summary-list\"><li>Ш → ш</li><li>Сп/ст в начале → шп/шт</li><li>qu → kv</li><li>z → c</li><li>V часто → ж</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Основы глаголов</h3>\n            <p class=\"kurss-lesson-intro\">Глаголы и спряжения лекции 1.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Глаголы</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Коммен - прийти</div><div class=\"kurss-example\">gehen — iet</div><div class=\"kurss-example\">Стивен — стоять</div><div class=\"kurss-example\">Синген - петь</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich komme - я иду</div><div class=\"kurss-example\">Du kommst - ты придешь</div><div class=\"kurss-example\">Er kommt - он идет</div><div class=\"kurss-example\">Sie kommt - она ​​идет</div><div class=\"kurss-example\">Wir kommen - мы идем</div><div class=\"kurss-example\">Ихр коммт - ты идешь</div><div class=\"kurss-example\">Sie kommen - они/они приходят</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — es eju</div><div class=\"kurss-example\">du gehst — tu ej</div><div class=\"kurss-example\">Э-э, он идет</div><div class=\"kurss-example\">Sie geht - она ​​идет</div><div class=\"kurss-example\">Вир геен – мы идем</div><div class=\"kurss-example\">Ihr geht - ты идешь</div><div class=\"kurss-example\">Sie gehen – они/они идут</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich stehe - я стою</div><div class=\"kurss-example\">Du stehst - ты стоишь</div><div class=\"kurss-example\">Er steht - он стоит</div><div class=\"kurss-example\">Sie steht - она ​​стоит</div><div class=\"kurss-example\">Вир штеен - мы стоим</div><div class=\"kurss-example\">Ihr steht - ты стоишь</div><div class=\"kurss-example\">Sie stehen - они/они стоят</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — es dziedu</div><div class=\"kurss-example\">du singst — tu dziedi</div><div class=\"kurss-example\">Эр сингт - он поет</div><div class=\"kurss-example\">Sie Singt - она ​​поет</div><div class=\"kurss-example\">Вир синген - мы поем</div><div class=\"kurss-example\">Ihrsingt - ты поешь</div><div class=\"kurss-example\">Sie Singen - они/они поют</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Глаголы лекции 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielen — играть</div><div class=\"kurss-example\">Arbeiten — работать</div><div class=\"kurss-example\">Fragen - спрашивать</div><div class=\"kurss-example\">Antworten — отвечать</div><div class=\"kurss-example\">Rechnen — вычислять</div><div class=\"kurss-example\">Zeichnen — рисовать</div><div class=\"kurss-example\">Тун — делать</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele - я играю</div><div class=\"kurss-example\">Du spielst - ты играешь</div><div class=\"kurss-example\">Er spielt - он играет</div><div class=\"kurss-example\">Sie spielt - она ​​играет</div><div class=\"kurss-example\">Wir spielen - мы играем</div><div class=\"kurss-example\">Ihr spielt - ты играешь</div><div class=\"kurss-example\">Sie spielen - они/она играют</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich arbeite - я работаю</div><div class=\"kurss-example\">Du arbetest - ты работаешь</div><div class=\"kurss-example\">Er arbeitt - он работает</div><div class=\"kurss-example\">Sie arbeitt - она ​​работает</div><div class=\"kurss-example\">Wir arbeiten - мы работаем</div><div class=\"kurss-example\">Ihr arbeitt - ты работаешь</div><div class=\"kurss-example\">Sie arbeiten – они/они работают</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich frage - я спросил</div><div class=\"kurss-example\">Du fragst - спросишь ты</div><div class=\"kurss-example\">Эээ фрагмент - спрашивает он</div><div class=\"kurss-example\">Sie fragt - она ​​спрашивает</div><div class=\"kurss-example\">Wir fragen - мы просим</div><div class=\"kurss-example\">Их фрагмент - ты спрашиваешь</div><div class=\"kurss-example\">Sie fragen - они/они спрашивают</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — es atbildu</div><div class=\"kurss-example\">du antwortest — tu atbildi</div><div class=\"kurss-example\">Эээ антортет - он отвечает</div><div class=\"kurss-example\">Sie antortet - она ​​отвечает</div><div class=\"kurss-example\">Wir antworten - мы отвечаем</div><div class=\"kurss-example\">Их антортет - ты отвечаешь</div><div class=\"kurss-example\">Sie antworten – они/они отвечают</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich rechne - я вычисляю</div><div class=\"kurss-example\">Du rechnest - ты рассчитываешь</div><div class=\"kurss-example\">Эр рехнет - он вычисляет</div><div class=\"kurss-example\">Sie rechnet — его счет</div><div class=\"kurss-example\">Wir rechnen – вычисляем</div><div class=\"kurss-example\">Ихр речнет - ты рассчитай</div><div class=\"kurss-example\">Sie rechnen - они/ее счет</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich zeichne - я рисую</div><div class=\"kurss-example\">Du zeichnest — ты рисуешь</div><div class=\"kurss-example\">Er zeichnet - он рисует</div><div class=\"kurss-example\">Sie zeichnet - она ​​рисует</div><div class=\"kurss-example\">Wir zeichnen - рисуем</div><div class=\"kurss-example\">Ihr zeichnet — ты рисуешь</div><div class=\"kurss-example\">Sie zeichnen – они/она рисуют</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — es daru</div><div class=\"kurss-example\">du tust — tu dari</div><div class=\"kurss-example\">Э-э-э - он делает</div><div class=\"kurss-example\">Sie tut - она ​​делает</div><div class=\"kurss-example\">Вир тун - мы делаем</div><div class=\"kurss-example\">Ихр тут - ты делаешь</div><div class=\"kurss-example\">Sie tun - они/они делают</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Структура предложений</h3>\n            <p class=\"kurss-lesson-intro\">В вопросительном предложении глагол в немецком языке обычно стоит первым.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Примеры</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Вы общаетесь. - Ты приходи.</div><div class=\"kurss-example\">Откуда ты? «Ты идешь?»</div><div class=\"kurss-example\">Эр сингт. — Он поет.</div><div class=\"kurss-example\">Петь, э? — Он поет?</div><div class=\"kurss-example\">Вы спешите? «Ты стоишь?»</div><div class=\"kurss-example\">Да, я знаю. — Да, я стою.</div><div class=\"kurss-example\">Это правда? \"Вы собираетесь?\"</div><div class=\"kurss-example\">Да, с этим все в порядке. - Да, мы едем.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Вопросы со словом «было»</h4>\n              <p>Если вопрос начинается с вопросительного слова, глагол в немецком языке обычно стоит сразу после вопросительного слова.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Ko tu dari?</div><div class=\"kurss-example\">Это было так? - Что он делает?</div><div class=\"kurss-example\">Это было так? «Что она делает?»</div><div class=\"kurss-example\">Было ли это хорошо? - Что они делают?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Noliegums ar “nicht”</h4>\n              <p>Когда отрицание nicht относится к глаголу, оно обычно идет после глагола в немецком языке.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Я не говорю ничего. — Я не играю.</div><div class=\"kurss-example\">Пол Фрагт Нихт. — Пол не спрашивает.</div><div class=\"kurss-example\">Это не так. - Он не придет.</div><div class=\"kurss-example\">Они не поют. — Они/они не поют.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Teikumi no 2. lekcijas</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ты играешь? «Ты играешь?»</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Нет, я не играю, я работаю.</div><div class=\"kurss-example\">Пол fragt nicht, er arbeitt. — Пол не спрашивает, он работает.</div><div class=\"kurss-example\">Вы работаете? - Вы работаете?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Нет, я не работаю, я пою.</div><div class=\"kurss-example\">Was tut Paul? — Ko dara Pauls?</div><div class=\"kurss-example\">Эээ сказал. — Он играет.</div><div class=\"kurss-example\">Was tut Marie? — Ko dara Marija?</div><div class=\"kurss-example\">Они поют. — Она поет.</div><div class=\"kurss-example\">Пол играет, а Мари поет. — Пол играет, а Мария поет.</div><div class=\"kurss-example\">Петь? — Ты поешь?</div><div class=\"kurss-example\">Нет, мы ничего не знаем, мы работаем. — Нет, мы не поем, мы работаем.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Ko dara Pauls un Marija?</div><div class=\"kurss-example\">Они спрашивают. — Они спрашивают.</div><div class=\"kurss-example\">Они не ответили. — Они не отвечают.</div><div class=\"kurss-example\">Кто работает? - Кто работает?</div><div class=\"kurss-example\">Мы работаем. — Мы работаем.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Считаем и рисуем.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Они приходят, спрашивают, отвечают, работают, играют, поют и уходят.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Lekcija 2</h3>\n            <p class=\"kurss-lesson-intro\">Вторая лекция: диалоги, слова, произношение, грамматика и перевод.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogi / teikumi</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielen — играть • Играть</div>\n                  <div class=\"kurss-example\">Нет - нет</div>\n                  <div class=\"kurss-example\">nicht — ne</div>\n                  <div class=\"kurss-example\">Arbeiten — работать</div>\n                  <div class=\"kurss-example\">Fragen - спрашивать</div>\n                  <div class=\"kurss-example\">Что ты делаешь? — что он делает?</div>\n                  <div class=\"kurss-example\">Что вы думаете? — что они/они делают?</div>\n                  <div class=\"kurss-example\">aber — bet</div>\n                  <div class=\"kurss-example\">Antworten — отвечать</div>\n                  <div class=\"kurss-example\">Rechnen — вычислять</div>\n                  <div class=\"kurss-example\">Zeichnen — рисовать</div>\n                  <div class=\"kurss-example\">Marie — Marija</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izruna</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В словах ich, nicht, rechnen, zeichnen звук ч произносится мягко, как в латышских словах: technika, Fridrich.</div><div class=\"kurss-example\">В словах arbeiten, zeichnen дифтонг ei произносится примерно так же, как латышский плоский звук е, за которым следует i.</div><div class=\"kurss-example\">Группа согласных sp произносится как šp: spielen (špīlen).</div><div class=\"kurss-example\">В глаголе tun u произносится долго во всех лицах.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Galotnes ar e</h4>\n                  <div class=\"lesson1-grammar-note\">Если основа глагола оканчивается на т, д, хн, то е при сгибании стоит перед окончаниями -ст и -т.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Вопросительное слово</h4>\n                  <div class=\"lesson1-grammar-note\">В вопросительных предложениях, начинающихся с вопросительного слова, например: что? что? ВОЗ? почему? почему? и т. д., глагол стоит сразу после вопросительного слова.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Ko tu dari?</div><div class=\"kurss-example\">Это было так? - Что он делает?</div><div class=\"kurss-example\">Это было так? «Что она делает?»</div><div class=\"kurss-example\">Было ли это хорошо? - Что они делают?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Noliegums ar nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Если отрицание nicht относится к глаголу, то отрицаемое слово стоит после глагола.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Это не так. - Он не придет.</div><div class=\"kurss-example\">Они не поют. — Они не поют.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переводить</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 2 pārtulkošanas kartīte\">\n                    <span class=\"lesson1-training-progress\">Лекция 2 · Перевод: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Кто спрашивает?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Нажмите на карточку, чтобы увидеть немецкий перевод. После ответа следующий клик показывает следующую карточку.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Lekcija 6</h3>\n    <p class=\"kurss-lesson-intro\">Числа, множественное число, умлауты и формы множественного числа существительных.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogi / teikumi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Deny — находится, находится, лежит</div><div class=\"kurss-example\">Der Bleistift (блейштифт) — карандаш</div><div class=\"kurss-example\">Einige (эйниге) – какой-то</div><div class=\"kurss-example\">hinlegen — nolikt</div><div class=\"kurss-example\">legt hin — noliek</div><div class=\"kurss-example\">Видер - снова</div><div class=\"kurss-example\">Aufmachen — отменить</div><div class=\"kurss-example\">Er macht auf - он развязывает</div><div class=\"kurss-example\">Anspitzen (anšpicen) – высказывать мнение</div><div class=\"kurss-example\">Er spitzt an - он плюет</div><div class=\"kurss-example\">Sich setzen — садиться</div><div class=\"kurss-example\">Setts sich – садится</div><div class=\"kurss-example\">Дер Шлюссель (schlüsel) – ключ</div><div class=\"kurss-example\">das Fenster (fenster) — logs</div><div class=\"kurss-example\">Die Tafel (стол для штампов) - классная доска</div><div class=\"kurss-example\">Дер Гартен – сад</div><div class=\"kurss-example\">der Löffel — karote</div><div class=\"kurss-example\">Zählen (cēlen) – считать</div><div class=\"kurss-example\">die Nadel — adata</div><div class=\"kurss-example\">was ist das — kas tas ir?</div><div class=\"kurss-example\">der Hammer — veseris</div><div class=\"kurss-example\">die Hämmer — veseri</div><div class=\"kurss-example\">Дер Декель (dēr dekel) — обложка</div><div class=\"kurss-example\">Дер Теллер - тарелка</div><div class=\"kurss-example\">der Wagen — rati</div><div class=\"kurss-example\">der Schlitten — ragavas, kamanas</div><div class=\"kurss-example\">das Ding — lieta</div><div class=\"kurss-example\">die Dinge — lietas</div><div class=\"kurss-example\">Wie sind die Dinge? - как дела?</div><div class=\"kurss-example\">voll (fōl) — pilns</div><div class=\"kurss-example\">Леер - пустой</div><div class=\"kurss-example\">Schwer (швер) – тяжелый, трудный</div><div class=\"kurss-example\">leicht — viegls</div><div class=\"kurss-example\">der Eimer — spainis</div><div class=\"kurss-example\">Вивил - сколько</div><div class=\"kurss-example\">wieviel Nadeln — cik adatu</div><div class=\"kurss-example\">Hier (хир) – здесь</div><div class=\"kurss-example\">dort — tur</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izruna</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ä — обертон гласной «а» и произносится как короткая или длинная узкая «е».</div><div class=\"kurss-example\">Примеры: das Mädchen (mētchen), die Bänke (dī benke), der Vater (dēr fater), die Väter (dī fēter).</div><div class=\"kurss-example\">Ü — обертон гласной u. При его произношении губы должны быть сильно округлены и старайтесь произносить i круглыми губами.</div><div class=\"kurss-example\">Примеры: fünf, der Schlüssel.</div><div class=\"kurss-example\">Ö произносится округленными губами, пытаясь произнести е: der Löffel.</div><div class=\"kurss-example\">Удвоенная гласная представляет собой долгую гласную: leer.</div><div class=\"kurss-example\">Дифтонг eu произносится как oi: neun (ноин).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramatika un paskaidrojumi</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ударная приставка сложного глагола отделяется от глагола в настоящем времени и стоит в конце предложения.</div><div class=\"kurss-example\">Примеры: hinlegen — er legt hin • Aufmachen — er macht auf • Anspitzen — эр шпиц ан.</div><div class=\"kurss-example\">Число один стоит во всех трех порядках при использовании с существительным: ein в мужском роде, eine в женском порядке, ein в среднем порядке.</div><div class=\"kurss-example\">Примеры: ein Schüler – один студент • Эйне Шулерин - одна студентка • Ein Kind - один ребенок.</div><div class=\"kurss-example\">Числа: eins, zwei, drei, vier, fünf, sechs, sieben, acht, neun, zehn.</div><div class=\"kurss-example\">Saitain в немецком языке имеет форму единственного и множественного числа: der Schüler ist klein • Die Schüler sind klein.</div><div class=\"kurss-example\">Указательное местоимение в латышском языке меняется по числу и порядку, но в немецком языке оно употребляется в одной форме: das.</div><div class=\"kurss-example\">Примеры: это молоток – das ist ein Hammer • Это игла — das ist eine Nadel • Это молоты — das sind Hämmer • Это иглы — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen - телеги и der Schlitten - сани в латышском языке стоят во множественном числе, а в немецком эти слова употребляются в единственном и множественном числе.</div><div class=\"kurss-example\">Существительные мужского и среднего рода, оканчивающиеся на -er, -el, -en, часто не имеют окончания во множественном числе.</div><div class=\"kurss-example\">Примеры: der Hammer – die Hämmer • Дер Гартен — ди Гартен • Das Fenster — die Fenster • Das Messer — умереть Мессер.</div><div class=\"kurss-example\">Существительные женского рода, оканчивающиеся на -el, -er, во множественном числе принимают -n.</div><div class=\"kurss-example\">Примеры: die Nadel – die Nadeln • Die Feder — die Federn.</div><div class=\"kurss-example\">Исключения: die Mutter (мать) — die Mütter (матери) • Die Tochter (дочь) — die Töchter (дочери).</div><div class=\"kurss-example\">Неопределенный артикль не имеет множественного числа: das ist ein Wagen — das sind Wagen • Das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">В повествовательном предложении подлежащее-глагол занимает второе место: er legt den Schlüssel hin • Данн Легт эр ден Шлюссель Хин.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переводить</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 6 pārtulkošanas kartīte\"><span class=\"lesson1-training-progress\">Лекция 6 · Перевод: 1 / 21</span><span class=\"lesson1-training-text\">Пол берет карандаш и рисует.</span></button><p class=\"lesson1-training-hint\">Нажмите на карточку, чтобы увидеть немецкий перевод. После ответа следующий клик показывает следующую карточку.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Lekcija 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, винительный падеж, sitzen, fragen и окончание -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogi / teikumi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Sitzen (зицен) — сидеть</div>\n        <div class=\"kurss-example\">Fragen (фрэген) — спрашивать</div>\n        <div class=\"kurss-example\">Дер Лерер (dēr lērer) — учитель</div>\n        <div class=\"kurss-example\">Гут (достать) - хорошо</div>\n        <div class=\"kurss-example\">Вэнь - что</div>\n        <div class=\"kurss-example\">Лобен — хвалить</div>\n        <div class=\"kurss-example\">Дер Шулер (schüler) — студент</div>\n        <div class=\"kurss-example\">klein — mazs</div>\n        <div class=\"kurss-example\">groß (grōs) — liels</div>\n        <div class=\"kurss-example\">Ди Леререн - учитель</div>\n        <div class=\"kurss-example\">die Schülerin — skolniece</div>\n        <div class=\"kurss-example\">Schlecht (шлехт) – плохой</div>\n        <div class=\"kurss-example\">tadeln — pelt</div>\n        <div class=\"kurss-example\">oder (ōder) — vai</div>\n        <div class=\"kurss-example\">Das Kind (кинт) – ребенок</div>\n        <div class=\"kurss-example\">Артиг (ārtich) — болтливый</div>\n        <div class=\"kurss-example\">Умереть Муттер — мать</div>\n        <div class=\"kurss-example\">Либен - любить</div>\n        <div class=\"kurss-example\">Дер Фатер (fäter) — отец</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izruna</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Tz — двойной звук z, произносится как z: sitzen (zicen).</div>\n        <div class=\"kurss-example\">V в немецких словах произносится как f: der Vater (fäter).</div>\n        <div class=\"kurss-example\">SS называется escet и произносится как латышское s: groß (grōs), weiß (veis).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Именительный и винительный падеж</h4><div class=\"lesson1-grammar-note\">В латышском именительный падеж отвечает на вопрос кто?, а винительный падеж отвечает на вопрос что?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В немецком языке именительный вопрос — wer? лица и что? предметы.</div><div class=\"kurss-example\">Винительный вопрос: wen? лица и что? предметы.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Изменение артикля на винительный</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Фраген + винительный падеж</h4><div class=\"lesson1-grammar-note\">Немецкий глагол fragen требует винительного падежа.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">-in galotne</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Многие существительные женского рода образованы с окончанием -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Место глагола</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В повествовательном предложении глагол стоит на второй позиции.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переводить</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 5 pārtulkošanas kartīte\"><span class=\"lesson1-training-progress\">Лекция 5 · Перевод: 1 / 16</span><span class=\"lesson1-training-text\">Что любит отец?</span></button><p class=\"lesson1-training-hint\">Нажмите на карточку, чтобы увидеть немецкий перевод. После ответа следующий клик показывает следующую карточку.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Lekcija 4</h3>\n            <p class=\"kurss-lesson-intro\">Винительный падеж, nehmen, hinlegen, hinausgehen и прилагательные.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogi / teikumi</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Немен (nēmen) – брать</div><div class=\"kurss-example\">Er nimmt (нимт) - он берет</div><div class=\"kurss-example\">Дер Федерхальтер (dēr fēderhalter) – пернатый</div><div class=\"kurss-example\">Эйнен Федерхальтер - держатель перьев</div><div class=\"kurss-example\">Zeigen — показывать</div><div class=\"kurss-example\">Шварц (schwarz) – черный</div><div class=\"kurss-example\">weiß (veis) — balts</div><div class=\"kurss-example\">Умереть Федер - перо</div><div class=\"kurss-example\">eine Feder — spalvu</div><div class=\"kurss-example\">Шпиц (špic) – остроконечный</div><div class=\"kurss-example\">hinlegen — nolikt</div><div class=\"kurss-example\">legt hin — noliek</div><div class=\"kurss-example\">Дас Мэдхен (mētchen) — девушка</div><div class=\"kurss-example\">das Messer — nazis</div><div class=\"kurss-example\">ein Messer — nazi</div><div class=\"kurss-example\">scharf — ass</div><div class=\"kurss-example\">Стампф (stumpf) — тупой, тупой</div><div class=\"kurss-example\">dann — tad</div><div class=\"kurss-example\">Хинаус — выход</div><div class=\"kurss-example\">Hinausgehen – выходи, выходи</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izruna</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Окончания -en, -er, -el безударные, поэтому е в этих окончаниях слабо слышна: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">H в немецком языке может быть как звуком, так и показателем длины предшествующей гласной.</div><div class=\"kurss-example\">Если h длинный, он не произносится как звук: немен (nēmen).</div><div class=\"kurss-example\">Если за гласной следует только одна согласная, гласная произносится долго: die (dī) Feder (федер), den (ден).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Винительный падеж</h4><div class=\"lesson1-grammar-note\">В женском и среднем роде винительный падеж равен именительному. Меняется только очередь мужчин.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Местоимения</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Эээ - очередь мужчин</div><div class=\"kurss-example\">Сие - женская очередь</div><div class=\"kurss-example\">Я - средний раунд</div><div class=\"kurss-example\">Во множественном числе — сие</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Разделяемые глаголы</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Прилагательные</h4><div class=\"lesson1-grammar-note\">Если прилагательное в предложении является прилагательным, оно не меняется ни по падежу, ни по числу.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Noliegums ar nicht</h4><div class=\"lesson1-grammar-note\">Если nicht отрицает прилагательное, оно стоит перед отрицаемым словом.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Существительные, оканчивающиеся на -chen и -lein, стоят в среднем порядке: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переводить</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 4 pārtulkošanas kartīte\"><span class=\"lesson1-training-progress\">Лекция 4 · Перевод: 1 / 16</span><span class=\"lesson1-training-text\">Девушка берет стержень пера.</span></button><p class=\"lesson1-training-hint\">Нажмите на карточку, чтобы увидеть немецкий перевод. После ответа следующий клик показывает следующую карточку.</p></div></div></details>",
  "kurssLesson3": "            <h3>Lekcija 3</h3>\n            <p class=\"kurss-lesson-intro\">Третья лекция: диалоги, слова, произношение, грамматика и перевод.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogi / teikumi</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kas</div><div class=\"kurss-example\">was — kas</div><div class=\"kurss-example\">Иер — здесь</div><div class=\"kurss-example\">dort — tur</div><div class=\"kurss-example\">der Tisch — galds</div><div class=\"kurss-example\">ein Tisch — galds</div><div class=\"kurss-example\">die Bank — sols</div><div class=\"kurss-example\">eine Bank — sols</div><div class=\"kurss-example\">Liegen – лежать</div><div class=\"kurss-example\">Лжец здесь, в Эйн-Бухе? — Здесь/есть ли здесь книга?</div><div class=\"kurss-example\">Дас Бух - книга</div><div class=\"kurss-example\">Эйн-Бух — книга</div><div class=\"kurss-example\">Hängen — вешать</div><div class=\"kurss-example\">das Bild — bilde</div><div class=\"kurss-example\">ein Bild — bilde</div><div class=\"kurss-example\">Die Tafel - доска</div><div class=\"kurss-example\">Эйне Тафель - доска</div><div class=\"kurss-example\">Wie – кто-то, что</div><div class=\"kurss-example\">ist — ir</div><div class=\"kurss-example\">dick — biezs, resns</div><div class=\"kurss-example\">Das Heft - блокнот</div><div class=\"kurss-example\">Эйн Хефт - блокнот</div><div class=\"kurss-example\">Dünn – тонкий, тонкий</div><div class=\"kurss-example\">niedrig — zems</div><div class=\"kurss-example\">hoch — augsts</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izruna</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Долгий звук ī в немецком языке обозначается т.е.:liegen (лиген), hier (хир), wie (ви).</div><div class=\"kurss-example\">Ск — двойной к: дик (дикк).</div><div class=\"kurss-example\">В прилагательных и наречиях окончание -ig звучит как легкое -ich: niedrig (нидрих).</div><div class=\"kurss-example\">Если окончание -ig оканчивается на е: -ige, то г произносится как определенный звук г: niedrige (нидриге) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Предмет предложения</h4><div class=\"lesson1-grammar-note\">Подлежащее в предложении в немецком языке отвечает на вопрос wer? / что? и стоит в именительном падеже.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">С нами? просит лиц.</div><div class=\"kurss-example\">С чем? просит предметы.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artikuli</h4><div class=\"lesson1-grammar-note\">В немецком языке существительное имеет 3 падежа: мужской, женский и средний. Существительным обычно предшествует слово, называемое артиклем. Это слово не переводится.</div><h5 class=\"lesson2-subtitle\">Noteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Мужской раунд - дер</div><div class=\"kurss-example\">Женская очередь - умереть</div><div class=\"kurss-example\">Средний раунд — дас</div><div class=\"kurss-example\">Определенный артикль во множественном числе для всех трех порядков – die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Nenoteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Мужская очередь - эйн</div><div class=\"kurss-example\">Женская очередь - eine</div><div class=\"kurss-example\">Средний раунд — эйн</div><div class=\"kurss-example\">Неопределенный артикль не имеет множественного числа.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Имена собственные</h4><div class=\"lesson1-grammar-note\">Артикль не употребляется перед именами собственными.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Место глагола</h4><div class=\"lesson1-grammar-note\">В повествовательном предложении глагол стоит на второй позиции.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">В немецком языке о предметах, стоящих вертикально, говорят, что объект стоит:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Говорят, что предметы, находящиеся в горизонтальном положении, лежат:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Также могут висеть предметы:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переводить</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 3 pārtulkošanas kartīte\"><span class=\"lesson1-training-progress\">Лекция 3 · Перевод: 1 / 22</span><span class=\"lesson1-training-text\">Ты считаешь</span></button><p class=\"lesson1-training-hint\">Нажмите на карточку, чтобы увидеть немецкий перевод. После ответа следующий клик показывает следующую карточку.</p></div></div></details>",
  "kurssLesson7": "            <h3>Lekcija 7</h3>\n            <p class=\"kurss-lesson-intro\">Седьмая лекция: Повелительное наклонение, форма обращения и множественное число.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogi / teikumi</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Синген - петь</div><div class=\"kurss-example\">singe — dziedi</div><div class=\"kurss-example\">singt — dziediet</div><div class=\"kurss-example\">singen Sie — dziediet</div><div class=\"kurss-example\">Das Lied (дас лит) — песня</div><div class=\"kurss-example\">Си - Ты</div><div class=\"kurss-example\">Zählen — считать</div><div class=\"kurss-example\">das Fräulein (froilein) — jaunkundze</div><div class=\"kurss-example\">der Müller — dzirnavnieks</div><div class=\"kurss-example\">Öffnen — открывать</div><div class=\"kurss-example\">das Fenster (fenster) — logs</div><div class=\"kurss-example\">alle — visi</div><div class=\"kurss-example\">Der Spiegel (шпигель) – зеркало</div><div class=\"kurss-example\">der Lappen — lupata, slaukis</div><div class=\"kurss-example\">Дер Шпатен – лопата</div><div class=\"kurss-example\">der Besen — slota</div><div class=\"kurss-example\">Умереть Шауфель - лопата</div><div class=\"kurss-example\">Die Schüssel - чаша</div><div class=\"kurss-example\">das Zimmer — istaba</div><div class=\"kurss-example\">Дас Уфер (üfer) — берег</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izruna</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sp в начале слова или слога произносится как šp: der Spiegel.</div><div class=\"kurss-example\">Sch произносится как латышское š: die Schaufel (ди шауфель), die Schüssel (ди шусел).</div><div class=\"kurss-example\">Дифтонг äu произносится как латышский oi: das Fräulein (das froilein).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Выражение команды</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Командное выражение во 2-м лице единственного числа соответствует глаголу во 2-м лице единственного числа без окончания лица -st, с добавлением окончания -e.</div><div class=\"kurss-example\">Примеры: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Очень часто окончание -е не употребляется, если с ним форма команды становится односложной: гех!, стех!, комм!, ту!, пой!, фраг!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Команда во множественном числе</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Форма команды во 2-м лице множественного числа аналогична форме 2-го лица настоящего множественного числа, но используется без местоимения.</div><div class=\"kurss-example\">Примеры: antwortet!, arbeitt!, öffnett!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Uzrunas forma ar Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Форма обращения на «Вы» напоминает третье лицо множественного числа. Местоимение Sie пишется с заглавной буквы и стоит после глагола.</div><div class=\"kurss-example\">Примеры: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">У глагола öffent для облегчения произношения между основой и окончанием во 2-м и 3-м лице единственного числа и во 2-м лице множественного числа ставится е: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Упражнение</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 7 vingrinājuma kartīte\"><span class=\"lesson1-training-progress\">Lekcija 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">Fragen - спрашивать</span></button><p class=\"lesson1-training-hint\">Коснитесь карточки, чтобы увидеть формы команд.</p></div></div></details>",
  "kurssLesson1": "            <h3>Lekcija 1</h3>\n            <p class=\"kurss-lesson-intro\">Первая лекция: глаголы в настоящем времени, слова, произношение, грамматика и перевод.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Глаголы в настоящем времени</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Глаголы и их спряжения в настоящем времени.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>Коммен - прийти</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>Я иду</span><span>du</span><strong>kommst</strong><span>Ты приходишь</span><span>er / sie</span><strong>kommt</strong><span>Он/она придет</span><span>wir</span><strong>kommen</strong><span>Мы идем</span><span>ihr</span><strong>kommt</strong><span>Ты идешь</span><span>sie / Sie</span><strong>kommen</strong><span>Они/ты идешь</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — iet</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>es eju</span><span>du</span><strong>gehst</strong><span>tu ej</span><span>er / sie</span><strong>geht</strong><span>Он/она идет</span><span>wir</span><strong>gehen</strong><span>Мы собираемся</span><span>ihr</span><strong>geht</strong><span>Вы идете</span><span>sie / Sie</span><strong>gehen</strong><span>Они/ты идешь</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>Стивен — стоять</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>Я стою</span><span>du</span><strong>stehst</strong><span>Ты стоишь</span><span>er / sie</span><strong>steht</strong><span>Он/она стоит</span><span>wir</span><strong>stehen</strong><span>Мы стоим</span><span>ihr</span><strong>steht</strong><span>Ты стоишь</span><span>sie / Sie</span><strong>stehen</strong><span>Они/ты стоишь</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>Синген - петь</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>es dziedu</span><span>du</span><strong>singst</strong><span>tu dziedi</span><span>er / sie</span><strong>singt</strong><span>Он/она поет</span><span>wir</span><strong>singen</strong><span>Мы поем</span><span>ihr</span><strong>singt</strong><span>Ты поешь</span><span>sie / Sie</span><strong>singen</strong><span>Они/ты поешь</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Примеры</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Имена</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Примерное произношение слов дано в скобках латышскими буквами.<br>Это также следует учитывать в будущих лекциях.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Вир (мужчина) – мы</div><div class=\"kurss-example\">В слове «вир» буква «и» произносится долго.</div><div class=\"kurss-example\">Коммен (komen) – прийти</div><div class=\"kurss-example\">Gehen (gē-en) — идти</div><div class=\"kurss-example\">Stehen (šte-en) — стоять</div><div class=\"kurss-example\">Singen (зинген) — петь</div><div class=\"kurss-example\">Du(dû)kommst – ты придешь</div><div class=\"kurss-example\">Эр(эр)коммт - он идёт</div><div class=\"kurss-example\">Sie (zī) kommt – она приходит</div><div class=\"kurss-example\">Wer (вер) – что?</div><div class=\"kurss-example\">Если (да) — да</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izruna</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">На лекциях дается правильное произношение слов, отмеченных латышскими буквами.</div><div class=\"kurss-example\">Вир (мужчина) – мы. В слове вири всегда произносится долго.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Инфинитив</h4><div class=\"lesson1-grammar-note\">Основная форма глагола. Обычно инфинитив оканчивается на -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Tagadnes galotnes</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Noņem <span class=\"lesson1-ending-accent\">-en</span> no darbības vārda pamatformas un pieliec galotni.</strong></p><p>Пример: коммен → комм + окончание</p><div class=\"lesson1-ending-process\" aria-label=\"Tagadnes galotnes veidošanas process\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>pamatforma</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>noņem <span class=\"lesson1-ending-accent\">-en</span></strong><span>paliek sakne</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>sakne</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>pieliec galotni</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Примеры</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Вопросительные предложения</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>В вопросительном предложении на немецком языке глагол обычно перемещается на первую позицию.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">На латышском:<br>Ты приходишь<br>Ты идешь?</div><div class=\"kurss-example\">По-немецки:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">Du kommst - ты придешь<br>Откуда ты? — ты придешь?</div><div class=\"kurss-example\">Эр сингт - он поет<br>Петь, а? — он поет?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Личное отличие</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt - он идет</div><div class=\"kurss-example\">Sie kommt - она ​​идет</div><div class=\"kurss-example\">Sie kommen - они/они приходят</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переводить</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 1 treniņa kartīte\">\n                    <span class=\"lesson1-training-progress\">Лекция 1 · Перевод: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Ты идешь?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Нажмите на карточку, чтобы увидеть немецкий перевод. После ответа следующий клик показывает следующую карточку.</p>\n                </div>\n              </div>\n            </details>"
};

